package com.personal.assistant.module.backup.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.backup.entity.BackupRecord;import com.personal.assistant.module.backup.mapper.BackupRecordMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
@Service public class BackupService{private final BackupRecordMapper records;private final AtomicBoolean running=new AtomicBoolean();@Value("${app.backup.script:/app/scripts/backup.sh}")private String script;@Value("${app.backup.directory:/app/backup}")private String directory;@Value("${app.backup.retention-days:14}")private int retentionDays;public BackupService(BackupRecordMapper r){records=r;}public List<BackupRecord> list(){return records.selectList(new LambdaQueryWrapper<BackupRecord>().orderByDesc(BackupRecord::getStartedAt).last("limit 100"));}public BackupRecord runFullBackup(){if(!running.compareAndSet(false,true))throw new BusinessException(ErrorCode.BUSINESS_ERROR,"已有备份任务正在运行");BackupRecord r=new BackupRecord();r.setBackupType("FULL");r.setStatus("RUNNING");r.setStartedAt(LocalDateTime.now());records.insert(r);try{Path path=Path.of(script);if(!Files.exists(path))throw new IllegalStateException("备份脚本不存在: "+script);ProcessBuilder pb=new ProcessBuilder("sh",script);pb.redirectErrorStream(true);pb.environment().put("BACKUP_DIR",directory);pb.environment().put("RETENTION_DAYS",String.valueOf(retentionDays));Process p=pb.start();String output=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(!p.waitFor(10,TimeUnit.MINUTES)){p.destroyForcibly();throw new IllegalStateException("备份执行超时");}if(p.exitValue()!=0)throw new IllegalStateException("备份失败: "+output.trim());String file=Arrays.stream(output.split("\\R")).filter(x->x.startsWith("BACKUP_FILE=")).map(x->x.substring(12)).findFirst().orElse(null);r.setFilePath(file);if(file!=null&&Files.exists(Path.of(file)))r.setFileSize(Files.size(Path.of(file)));r.setStatus("SUCCESS");r.setMessage(output.trim());return r;}catch(Exception e){r.setStatus("FAILED");r.setMessage(e.getMessage());throw new BusinessException(ErrorCode.BUSINESS_ERROR,e.getMessage());}finally{r.setFinishedAt(LocalDateTime.now());records.updateById(r);running.set(false);}}}